
package org.firstinspires.ftc.teamcode.utilities;

import com.pedropathing.algorithm.ForesightConfig;
import com.pedropathing.controllers.Controller;
import com.pedropathing.math.Matrix;
import com.pedropathing.math.Vector2D;

public final class PedroForesightConfig {

    private PedroForesightConfig() {
    }

    // Configuration generated by Pedro AutoTune.
    public static ForesightConfig create() {

        return new ForesightConfig(c -> {

            Controller primaryTranslationalForward =
                    Controller.proportional(0.1737025114282185);

            Controller secondaryTranslationalForward =
                    Controller.proportional(0.0641784365561392);

            Controller primaryTranslationalLateral =
                    Controller.proportional(0.2642156813669011);

            Controller secondaryTranslationalLateral =
                    Controller.proportional(0.09762063429203846);

            c.forwardTranslational.set(
                    Controller.piecewise(
                                    secondaryTranslationalForward)
                            .put(2.5, primaryTranslationalForward));

            c.strafeTranslational.set(
                    Controller.piecewise(
                                    secondaryTranslationalLateral)
                            .put(2.5, primaryTranslationalLateral));

            c.coast.set(
                    Controller.proportionalFeedforward(
                            0.014931372562284521));

            c.brake.set(
                    Controller.proportionalFeedforward(
                            0.012691666677941842));

            c.headingFeedback.set(
                    Controller.proportional(
                            20.183665969632138));

            c.headingBrakeCoefficients.set(
                    Vector2D.cartesian(
                            0.03096201510591507,
                            0.012777833557785917));

            c.linearBrakeCoefficients.set(
                    Matrix.diag(
                            0.04236183803233171,
                            0.021887519090280142));

            c.quadraticBrakeCoefficients.set(
                    Matrix.diag(
                            0.0028594412964190884,
                            0.003377039609117658));

            c.maxAchievableForwardVelocity.set(
                    65.5969919211119);

            c.maxAchievableStrafeVelocity.set(
                    57.5595385195227);

            c.naturalForwardDeceleration.set(
                    23.154329340587545);

            c.naturalStrafeDeceleration.set(
                    30.88011205388763);
        });
    }
}
